def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda x: sum(v == x for row in grid for v in row))
    colors = set(v for row in grid for v in row) - {bg}
    seen=set()
    for color in colors:
        seen=set()
        for sr in range(h):
            for sc in range(w):
                if grid[sr][sc] != color or (sr,sc) in seen: continue
                stack=[(sr,sc)]; seen.add((sr,sc)); cells=[]
                while stack:
                    r,c=stack.pop(); cells.append((r,c))
                    for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                        if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and grid[nr][nc]==color:
                            seen.add((nr,nc)); stack.append((nr,nc))
                r0,r1=min(r for r,c in cells),max(r for r,c in cells)
                c0,c1=min(c for r,c in cells),max(c for r,c in cells)
                if r1-r0<2 or c1-c0<2: continue
                if (all(grid[r0][c]==color and grid[r1][c]==color for c in range(c0,c1+1)) and
                    all(grid[r][c0]==color and grid[r][c1]==color for r in range(r0,r1+1))):
                    # Fill color is determined by the count of interior cells: odd -> 7, even -> 2.
                    fill = 7 if ((r1-r0-1)*(c1-c0-1)) % 2 else 2
                    for r in range(r0+1,r1):
                        for c in range(c0+1,c1):
                            if grid[r][c] == bg:
                                out[r][c]=fill
    return out
